import{_ as d,c as o,o as c,b0 as t}from"./chunks/framework.BWMBvyU7.js";const a="/programming-docs/assets/image-20220529165818190.BVO4KgId.png",P="/programming-docs/assets/image-20220529171146924.CsmGgxXw.png",r="/programming-docs/assets/image-20220618090342797.gb6yCQ41.png",i="/programming-docs/assets/image-20220618092329413.CBXXH9h1.png",l="/programming-docs/assets/image-20220618092449363.BgWu9EUB.png",n="/programming-docs/assets/image-20220618092638770.DFd5i3JA.png",D="/programming-docs/assets/image-20220618093006767.OsrnKRtE.png",u=JSON.parse('{"title":"LV025-IP协议简介","description":null,"frontmatter":{"title":"LV025-IP协议简介","date":"2026-03-16T14:16:32.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/net/net-basic/126d38f258401af3882ae48d","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T14:16:32.431Z","fulluuid":"3882ae48d93f4844bf33eedbf3167dda","useduuid":"3882ae48d"}},"headers":[],"relativePath":"sdoc/net/net-basic/126d38f258401af3882ae48d.md","filePath":"sdoc/04-网络相关/10-网络基础/LV025-IP协议简介.md","lastUpdated":1773672539000}'),p={name:"sdoc/net/net-basic/126d38f258401af3882ae48d.md"};function C(s,e,H,I,h,m){return c(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="lv025-ip协议简介" tabindex="-1">LV025-IP协议简介 <a class="header-anchor" href="#lv025-ip协议简介" aria-label="Permalink to &quot;LV025-IP协议简介&quot;">​</a></h1><p>本文主要是网络基础——IP协议简介的相关笔记，若笔记中有错误或者不合适的地方，欢迎批评指正😃。</p><p>这里简单了解一下IP协议吧。这一节的笔记挺迷糊的，有坑的话后边再补充。</p><h2 id="一、ip协议简介" tabindex="-1">一、<code>IP</code>协议简介 <a class="header-anchor" href="#一、ip协议简介" aria-label="Permalink to &quot;一、`IP`协议简介&quot;">​</a></h2><p><code>IP</code>，全称<code>Internet Protocol</code>，即网际互连协议，是<code>TCP/IP</code>体系中的网络层协议。设计<code>IP</code>的目的是提高网络的可扩展性：一是解决互联网问题，实现大规模、异构网络的互联互通；二是分割顶层网络应用和底层网络技术之间的耦合关系，以利于两者的独立发展。根据端到端的设计原则，<code>IP</code>只为主机提供一种无连接、不可靠的、尽力而为的数据包传输服务。</p><p><code>IP</code>是整个<code>TCP/IP</code>协议族的核心，也是构成互联网的基础。<code>IP</code>位于<code>TCP/IP</code>模型的网络层(相当于<code>OSI</code>模型的网络层)，它可以向传输层提供各种协议的信息，例如<code>TCP</code>、<code>UDP</code>等；对下可将<code>IP</code>信息包放到链路层，通过以太网、令牌环网络等各种技术来传送。</p><p><code>IP</code>主要包含三方面内容：<code>IP</code>编址方案、分组封装格式及分组转发规则。<code>IP</code>所提供的服务大致可归纳为两类：<code>IP</code>信息包的传送和 <code>IP</code>信息包的分割与重组。这里就不详细展开写了，可以看百度百科，这部分笔记就来自于百度啦。</p><h2 id="二、ip数据报文" tabindex="-1">二、<code>IP</code>数据报文 <a class="header-anchor" href="#二、ip数据报文" aria-label="Permalink to &quot;二、`IP`数据报文&quot;">​</a></h2><p>在<code>TCP/IP</code> 协议中，使用 <code>IP</code> 协议传输数据的包被称为 <code>IP</code> 数据包，每个数据包都包含 <code>IP</code> 协议规定的内容。<code>IP</code> 协议规定的这些内容被称为 <code>IP</code> 数据报文（<code>IP Datagram</code>）或者 <code>IP</code> 数据报。</p><p><code>IP</code> 数据报文由首部（称为报头）和数据两部分组成。首部的前一部分是固定长度，共 <code>20</code> 字节，是所有 <code>IP</code> 数据报必须具有的，在首部的固定部分的后面是一些可选字段，其长度是可变的。</p><h3 id="_1-ipv4数据报文首部结构" tabindex="-1">1. <code>IPv4</code>数据报文首部结构 <a class="header-anchor" href="#_1-ipv4数据报文首部结构" aria-label="Permalink to &quot;1. `IPv4`数据报文首部结构&quot;">​</a></h3><img src="'+a+'" alt="image-20220529165818190" style="zoom:50%;"><h3 id="_2-ipv6数据报文首部结构" tabindex="-1">2. <code>IPv6</code>数据报文首部结构 <a class="header-anchor" href="#_2-ipv6数据报文首部结构" aria-label="Permalink to &quot;2. `IPv6`数据报文首部结构&quot;">​</a></h3><img src="'+P+'" alt="image-20220529171146924" style="zoom:53%;"><h2 id="三、ip协议相关技术" tabindex="-1">三、<code>IP</code>协议相关技术 <a class="header-anchor" href="#三、ip协议相关技术" aria-label="Permalink to &quot;三、`IP`协议相关技术&quot;">​</a></h2><h3 id="_1-dns" tabindex="-1">1. <code>DNS</code> <a class="header-anchor" href="#_1-dns" aria-label="Permalink to &quot;1. `DNS`&quot;">​</a></h3><p><code>TCP/IP</code>提供了通过<code>IP</code>地址来连接到设备的功能，但对用户来讲，记住某台设备的<code>IP</code>地址是相当困难的，因此专门设计了一种字符串形式的主机命名机制，这些主机名与<code>IP</code>地址相对应。在<code>IP</code>地址与主机名之间需要有一种转换和查询机制，提供这种机制的系统就是域名系统<code>DNS</code>（<code>Domain Name System</code>）。</p><p>它作为将域名和<code>IP</code>地址相互映射的一个分布式数据库，能够使人更方便地访问互联网。<code>DNS</code>使用<code>UDP</code>端口<code>53</code>。当前，对于每一级域名长度的限制是<code>63</code>个字符，域名总长度则不能超过<code>253</code>个字符。</p><p>我们平时在上网的时候，通常使用的方式是域名，而不是 <code>IP</code> 地址，比如我们要搜索东西，需要用百度的话，我们输入的网址是<code>www.baidu.com</code>，而不是<code>IP</code>地址。那么实现这从<code>IP</code>地址到域名的技术就是 <code>DNS</code> 域名解析，<code>DNS</code> 可以将域名网址自动转换为具体的 <code>IP</code> 地址。</p><h4 id="_1-1-域名的层级" tabindex="-1">1.1 域名的层级 <a class="header-anchor" href="#_1-1-域名的层级" aria-label="Permalink to &quot;1.1 域名的层级&quot;">​</a></h4><p><code>DNS</code> 中的域名都是用句点<code>.</code>来分隔的，比如 <code>www.server.com</code>，这里的句点代表了不同层次之间的界限。在域名中，<strong>越靠右的位置表示其层级越高</strong>。</p><p>域名系统的名字空间是层次结构的，类似<code>Windows</code>的文件名。它可看作是一个树状结构，域名系统不区分树内节点和叶子节点，而统称为节点，不同节点可以使用相同的标记。所有节点的标记只能由<code>3</code>类字符组成：<code>26</code>个英文字母(<code>a～z</code>)、<code>10</code>个阿拉伯数字(<code>0～9</code>)和英文连词号(<code>-</code>)，并且标记的长度不得超过<code>22</code>个字符。</p><p>最上层节点的域名称为顶级域名(<code>TLD</code>，<code>Top-Level Domain</code>)，如<code>.com</code>、<code>.net</code>、<code>.cn</code> 等，第二层节点的域名称为二级域名，如<code>baidu.com</code>，依此类推。例如，</p><ul><li><code>https://www.server.com</code> 是一个网址；</li><li><code>www.server.com</code>是域名；</li><li><code>.com</code> 是顶级域名；</li><li><code>server.com</code> 是二级域名；</li><li><code>www.server.com</code> 是三级域名</li></ul><p>实际上域名最后还有一个点，比如 <code>www.server.com.</code>，这个最后的一个点代表根域名。也就是说，<code>.</code> 根域是在最顶层，它的下一层就是 <code>.com</code> 顶级域，再下面是 <code>server.com</code>。</p><h4 id="_1-2-域名的分配" tabindex="-1">1.2 域名的分配 <a class="header-anchor" href="#_1-2-域名的分配" aria-label="Permalink to &quot;1.2 域名的分配&quot;">​</a></h4><p>最初所有机器使用的名字构成了一个非等级的名字空间，由字符序列组成所有的名字。网络信息中心<code>NIC</code>（<code>Network Information Center</code>）管理这个名字空间，并负责接纳新名字。非等级名字空间由于自身的特点不能管理大量的机器名字，主要有如下原因：</p><ul><li>名字由字符序列组成，存在潜在的命名冲突。</li><li>名字空间的管理结构位于一个站点，机器数量的不断增多对管理工作带来很大负担。</li><li>名字到<code>IP</code>地址的映射经常发生变化，导致维护域名空间的工作量巨大。</li></ul><p>后来<code>TCP/IP</code>把<code>DNS</code>的域名设计成了分级的结构。<code>Internet</code>域名结构由<code>TCP/IP</code>协议栈中的<code>DNS</code>进行定义。<code>DNS</code>把因特网划分成多个顶级域。顶级域采用组织模式和地理模式的划分模式。地理模式按照国家进行划分等。</p><table><tbody><tr><td align="center" width="180px">顶级Internet域名</td><td align="center">含义</td></tr><tr><td align="center" width="180px">com</td><td align="left">商业组织</td></tr><tr><td align="center" width="180px">edu</td><td align="left">教育机构</td></tr><tr><td align="center" width="180px">gov</td><td align="left">政府机构</td></tr><tr><td align="center" width="180px">mil</td><td align="left">军事部门</td></tr><tr><td align="center" width="180px">net</td><td align="left">主要网络支持中心</td></tr><tr><td align="center" width="180px">int</td><td align="left">国际组织</td></tr><tr><td align="center" width="180px">org</td><td align="left">其他组织</td></tr><tr><td align="center" width="180px">国家代码</td><td align="left">其他各个国家（按照地理模式划分）</td></tr></tbody></table><p>域名由因特网域名与地址管理机构(<code>ICANN</code>，<code>Internet Corporation for Assigned Names and Numbers</code>)管理，这是为承担域名系统管理、<code>IP</code>地址分配、协议参数配置，以及主服务器系统管理等职能而设立的非盈利机构。<code>ICANN</code>为不同的国家或地区设置了相应的顶级域名，这些域名通常都由两个英文字母组成。例如：<code>.uk</code>代表英国、<code>.fr</code>代表法国、<code>.jp</code>代表日本。中国的顶级域名是<code>.cn</code>，<code>.cn</code>下的域名由<code>CNNIC</code>进行管理。</p><h4 id="_1-3-域名解析" tabindex="-1">1.3 域名解析 <a class="header-anchor" href="#_1-3-域名解析" aria-label="Permalink to &quot;1.3 域名解析&quot;">​</a></h4><p>因特网上的<code>DNS</code>服务器按照层次安排，根据不同层次的域名服务器所起的作用，可以把域名服务器分为<code>4</code>种不同的类型。</p><table><tbody><tr><td align="center" width="150px">根域名服务器 </td><td align="left">最高层次的域名服务器，也是最重要的域名服务器，全球有13个根域名服务器名称。一个根服务器的名字可以作为入口对应一组服务器集群来提供域名解析服务。</td></tr><tr><td align="center" width="150px">顶级域名服务器</td><td align="left">负责管理在该顶级域名服务器注册的下一级域名(二级域名)。所有顶级域名服务器的名称和IP地址是在根服务器注册的，也就是说，根域名服务器知道所有的顶级域名服务器的名称和IP地址。</td></tr><tr><td align="center" width="150px">权威域名服务器</td><td align="left">负责一个区的域名服务器，通常是指顶级域名以下的管理二级、三级、四级等域名的服务器。</td></tr><tr><td align="center" width="150px">本地域名服务器</td><td align="left">当一个主机(个人电脑)发出DNS请求时，查询请求就被发送到本地域名服务器，本地域名服务器负责回答这个查询，或者代替主机向域名空间中不同层次的权威域名服务器查询，再把查询的结果返回给主机。</td></tr></tbody></table><p>层次关系如下图所示：</p><img src="'+r+'" alt="image-20220618090342797" style="zoom:50%;"><p>根域的 <code>DNS</code> 服务器信息保存在互联网中所有的 <code>DNS</code> 服务器中。这样一来，任何 <code>DNS</code> 服务器就都可以找到并访问根域 <code>DNS</code> 服务器了。因此，客户端只要能够找到任意一台 <code>DNS</code> 服务器，就可以通过它找到根域 <code>DNS</code> 服务器，然后再一路找到位于下层的某台目标 <code>DNS</code> 服务器。</p><p>下边就来了解一下解析流程吧：</p><ul><li>(1)客户端通过浏览器访问域名为 <code>www.server.com (http://www.server.com)</code>的网站，发起查询该域名的 <code>IP</code> 地址的 <code>DNS</code> 请求。该请求发送到了本地 <code>DNS</code> 服务器上。本地 <code>DNS</code> 服务器会首先查询它的缓存记录，如果缓存中有此条记录，就可以直接返回结果。如果没有，本地 <code>DNS</code> 服务器还要向 <code>DNS</code> 根服务器进行查询。</li><li>(2)本地 <code>DNS</code> 服务器向根服务器发送 <code>DNS</code> 请求，请求域名为 <code>www.server.com (http://www.server.com)</code>的 <code>IP</code> 地址。</li><li>(3)根服务器经过查询，没有记录该域名及 <code>IP</code> 地址的对应关系。但是会告诉本地 <code>DNS</code> 服务器，可以到域名服务器上继续查询，并给出域名服务器的地址（<code>.com</code> 服务器）。</li><li>(4)本地 <code>DNS</code> 服务器向 <code>.com</code> 服务器发送 <code>DNS</code> 请求，请求域名 <code>www.server.com (http://www.server.com)</code>的 <code>IP</code> 地址。</li><li>(5)<code>.com</code> 服务器收到请求后，不会直接返回域名和<code>IP</code>地址的对应关系，而是告诉本地 <code>DNS</code> 服务器，该域名可以在 <code>server.com</code> 域名服务器上进行解析获取 <code>IP</code> 地址，并告诉 <code>server.com</code> 域名服务器的地址。</li><li>(6)本地 <code>DNS</code> 服务器向 <code>server.com</code> 域名服务器发送 <code>DNS</code> 请求，请求域名<code>www.server.com (http://www.server.com)</code>的<code>IP</code>地址。</li><li>(7)<code>server.com</code> 服务器收到请求后，在自己的缓存表中发现了该域名和<code>IP</code>地址的对应关系，并将<code>IP</code>地址返回给本地 <code>DNS</code> 服务器。</li><li>(8)本地 <code>DNS</code> 服务器将获取到与域名对应的 <code>IP</code> 地址返回给客户端，并且将域名和 <code>IP</code> 地址的对应关系保存在缓存中，以备下次别的用户查询时使用。</li></ul><img src="'+i+'" alt="image-20220618092329413" style="zoom:50%;"><p>但是每次解析域名不一定都要经过那么多的步骤，浏览器会先看自身有没有对这个域名的缓存，如果有，就直接返回，如果没有，就去问操作系统，操作系统也会去看自己的缓存，如果有，就直接返回，如果没有，再去 <code>hosts</code> 文件看，也没有，才会去问本地 <code>DNS</code> 服务器。</p><h3 id="_2-dhcp" tabindex="-1">2. <code>DHCP</code> <a class="header-anchor" href="#_2-dhcp" aria-label="Permalink to &quot;2. `DHCP`&quot;">​</a></h3><p><code>DHCP</code>（<code>Dynamic Host Configuration Protocol</code>）即动态主机配置协议。它是一个局域网的网络协议，指的是由服务器控制一段<code>IP</code>地址范围，客户机登录服务器时就可以自动获得服务器分配的<code>IP</code>地址和子网掩码。我们的电脑通常都是通过 <code>DHCP</code> 动态获取 <code>IP</code> 地址，大大省去了配 <code>IP</code> 信息繁琐的过程。</p><p>难以想象，这部分笔记所学习的<code>DHCP</code>相关知识竟然是从一款产品的文档中获得的，不过说的确实很详细，感兴趣的话可以看这里：<a href="https://support.huawei.com/hedex/hdx.do?docid=EDOC1100203016&amp;lang=zh" target="_blank" rel="noreferrer">NetEngine AR 产品文档 (huawei.com)</a></p><p>【说明】关于<code>DHCP</code>的配置说明部分在这个手册的【配置→配置指南（通过命令行）→<code>IP</code>业务配置指南→<code>DHCP</code>配置】</p><h4 id="_2-1-使用dhcp有什么优势" tabindex="-1">2.1 使用<code>DHCP</code>有什么优势？ <a class="header-anchor" href="#_2-1-使用dhcp有什么优势" aria-label="Permalink to &quot;2.1 使用`DHCP`有什么优势？&quot;">​</a></h4><p>使用<code>DHCP</code>有如下优势：</p><ul><li>准确的<code>IP</code>配置：<code>IP</code>地址配置参数必须准确，并且在处理<code>192.168.XXX.XXX</code>之类的输入时，很容易出错。另外印刷错误通常很难解决，使用<code>DHCP</code>服务器可以最大程度地降低这种风险。</li><li>减少<code>IP</code>地址冲突：每个连接的设备都必须有一个<code>IP</code>地址。但是，每个地址只能使用一次，重复的地址将导致无法连接一个或两个设备的冲突。当手动分配地址时，尤其是在存在大量仅定期连接的端点（例如移动设备）时，可能会发生这种情况。<code>DHCP</code>的使用可确保每个地址仅使用一次。</li><li><code>IP</code>地址管理的自动化：如果没有<code>DHCP</code>，网络管理员将需要手动分配和撤消地址。跟踪哪个设备具有什么地址可能是徒劳的，因为几乎无法理解设备何时需要访问网络以及何时需要离开网络。<code>DHCP</code>允许将其自动化和集中化，因此网络专业人员可以从一个位置管理所有位置。</li><li>高效的变更管理：<code>DHCP</code>的使用使更改地址，范围或端点变得非常简单。例如，组织可能希望将其<code>IP</code>寻址方案从一个范围更改为另一个范围。<code>DHCP</code>服务器配置有新信息，该信息将传播到新端点。同样，如果升级并更换了网络设备，则不需要网络配置。</li></ul><h4 id="_2-2-dhcp组网" tabindex="-1">2.2 <code>DHCP</code>组网 <a class="header-anchor" href="#_2-2-dhcp组网" aria-label="Permalink to &quot;2.2 `DHCP`组网&quot;">​</a></h4><p>一种典型的组网如下图所示：</p><img src="'+l+'" alt="image-20220618092449363" style="zoom:50%;"><table><tbody><tr><td align="center" width="150px">DHCP服务器</td><td align="left">DHCP服务器负责从地址池中选择IP地址分配至DHCP客户端，还可以为DHCP客户端提供其他网络参数，如默认网关地址、DNS服务器地址和WINS服务器地址。DHCP服务器可以接收处理来自本网段或跨网段由DHCP中继转发的DHCP请求报文。</td></tr><tr><td align="center" width="150px">DHCP客户端</td><td align="left">DHCP客户端发送DHCP请求报文、通过BOOTP或DHCP协议请求获取IP地址等网络参数的设备。例如，IP电话、PC、手机、无盘工作站等。</td></tr><tr><td align="center" width="150px">DHCP中继 </td><td align="left">DHCP中继负责转发DHCP服务器和DHCP客户端之间的DHCP报文，协助DHCP服务器向DHCP客户端动态分配网络参数的设备。</td></tr></tbody></table><h4 id="_2-3-dhcp报文" tabindex="-1">2.3 <code>DHCP</code>报文 <a class="header-anchor" href="#_2-3-dhcp报文" aria-label="Permalink to &quot;2.3 `DHCP`报文&quot;">​</a></h4><p><code>DHCP</code>服务器与<code>DHCP</code>客户端之间通过<code>DHCP</code>报文进行通信。<code>DHCP</code>报文是基于<code>UDP</code>协议传输的。<code>DHCP</code>客户端向<code>DHCP</code>服务器发送报文时采用<code>68</code>端口号，<code>DHCP</code>服务器向<code>DHCP</code>客户端发送报文时采用<code>67</code>端口号。目前<code>DHCP</code>定义了如下八种类型报文:</p><table><tbody><tr><td align="center" width="160px">报文名称</td><td align="center">说明</td></tr><tr><td align="center" width="160px">DHCP DISCOVER</td><td align="left">DHCP客户端首次登录网络时进行DHCP交互过程发送的第一个报文，用来寻找DHCP服务器。</td></tr><tr><td align="center" width="160px">DHCP OFFER</td><td align="left">DHCP服务器用来响应DHCP DISCOVER报文，此报文携带了各种配置信息。</td></tr><tr><td align="center" width="160px">DHCP REQUEST </td><td align="left">此报文用于以下三种用途。客户端初始化后，发送广播的DHCP REQUEST报文来回应服务器的DHCP OFFER报文。客户端重启后，发送广播的DHCP REQUEST报文来确认先前被分配的IP地址等配置信息。当客户端已经和某个IP地址绑定后，发送DHCP REQUEST单播或广播报文来更新IP地址的租约。</td></tr><tr><td align="center" width="160px">DHCP ACK</td><td align="left">服务器对客户端的DHCP REQUEST报文的确认响应报文，客户端收到此报文后，才真正获得了IP地址和相关的配置信息。</td></tr><tr><td align="center" width="160px">DHCP NAK</td><td align="left">服务器对客户端的DHCP REQUEST报文的拒绝响应报文，例如DHCP服务器收到DHCP REQUEST报文后，没有找到相应的租约记录，则发送DHCP NAK报文作为应答，告知DHCP客户端无法分配合适IP地址。</td></tr><tr><td align="center" width="160px">DHCP DECLINE</td><td align="left">当客户端发现服务器分配给它的IP地址发生冲突时会通过发送此报文来通知服务器，并且会重新向服务器申请地址。</td></tr><tr><td align="center" width="160px">DHCP RELEASE</td><td align="left">客户端可通过发送此报文主动释放服务器分配给它的IP地址，当服务器收到此报文后，可将这个IP地址分配给其它的客户端。</td></tr><tr><td align="center" width="160px">DHCP INFORM</td><td align="left">DHCP客户端获取IP地址后，如果需要向DHCP服务器获取更为详细的配置信息（网关地址、DNS服务器地址），则向DHCP服务器发送DHCP INFORM请求报文。</td></tr></tbody></table><h4 id="_2-4-如何获取ip的" tabindex="-1">2.4 如何获取<code>IP</code>的？ <a class="header-anchor" href="#_2-4-如何获取ip的" aria-label="Permalink to &quot;2.4 如何获取`IP`的？&quot;">​</a></h4><p>只有跟<code>DHCP</code>客户端在同一个网段的<code>DHCP</code>服务器才能收到<code>DHCP</code>客户端广播的<code>DHCP DISCOVER</code>报文。当<code>DHCP</code>客户端与<code>DHCP</code>服务器不在同一个网段时，必须部署<code>DHCP</code>中继来转发<code>DHCP</code>客户端和<code>DHCP</code>服务器之间的<code>DHCP</code>报文。在<code>DHCP</code>客户端看来，<code>DHCP</code>中继就像<code>DHCP</code>服务器；在<code>DHCP</code>服务器看来，<code>DHCP</code>中继就像<code>DHCP</code>客户端。</p><h5 id="_2-4-1-无中继场景时dhcp客户端首次接入网络" tabindex="-1">2.4.1 无中继场景时DHCP客户端首次接入网络 <a class="header-anchor" href="#_2-4-1-无中继场景时dhcp客户端首次接入网络" aria-label="Permalink to &quot;2.4.1 无中继场景时DHCP客户端首次接入网络&quot;">​</a></h5><img src="'+n+'" alt="image-20220618092638770" style="zoom:50%;"><p>（1）发现阶段</p><p>客户端首先发起 <strong>DHCP 发现报文（DHCP DISCOVER）</strong> 的 <code>IP</code> 数据报，由于次接入网络的<code>DHCP</code>客户端没有 <code>IP</code> 地址，也不知道 <code>DHCP</code> 服务器的<code>IP</code>地址，为了获取到<code>DHCP</code>服务器的<code>IP</code>地址，<code>DHCP</code>客户端发送<code>DHCP DISCOVER</code>报文到链路层，然后链路层以广播方式发给<strong>同一网段内的所有设备</strong>（包括<code>DHCP</code>服务器或中继）。广播目的地址是 <code>255.255.255.255</code>（端口 <code>67</code>） 并且使用 <code>0.0.0.0</code>（端口 <code>68</code>） 作为源 <code>IP</code> 地址。</p><p><code>DHCP DISCOVER</code>报文中携带了客户端的<code>MAC</code>地址（<code>chaddr</code>字段）、需要请求的参数列表选项（<code>Option55</code>）、广播标志位（<code>flags</code>字段）等信息。</p><p>（2）提供阶段</p><p>与<code>DHCP</code>客户端位于同一网段的<code>DHCP</code>服务器都会接收到<code>DHCP DISCOVER</code>报文，<code>DHCP</code>服务器选择跟接收<code>DHCP DISCOVER</code>报文接口的<code>IP</code>地址处于同一网段的地址池，并且从中选择一个可用的<code>IP</code>地址，然后通过<code>DHCP OFFER</code>报文发送给<code>DHCP</code>客户端。</p><p>该报文仍然使用 <code>IP</code> 广播地址 <code>255.255.255.255</code>，该报文信息携带服务器提供可租约的 <code>IP</code> 地址、子网掩码、默认网关、<code>DNS</code> 服务器以及 <code>IP</code> 地址租用期。通常，<code>DHCP</code>服务器的地址池中会指定<code>IP</code>地址的租期，如果<code>DHCP</code>客户端发送的<code>DHCP DISCOVER</code>报文中携带了期望租期，服务器会将客户端请求的期望租期与其指定的租期进行比较，选择其中时间较短的租期分配给客户端。</p><blockquote><p>Tips：租期和地址池的概念：</p><ul><li><strong>租期</strong></li></ul><p><code>DHCP</code>服务器给每个分配给客户端的<code>IP</code>地址定义一个使用期限，该使用期限被称为租期。在租期到期前，<code>DHCP</code>客户端如果仍需要使用该<code>IP</code>地址，可以请求延长租期；如果不需要，可以主动释放该<code>IP</code>地址。在没有其他空闲地址可用的情况下，<code>DHCP</code>服务器会把客户端主动释放的<code>IP</code>地址分配给其他客户端。</p><p><code>DHCP</code>服务器动态分配的所有<code>IP</code>地址都受租期时长的限制，不同的<code>DHCP</code>服务器配置的租期时长可以不同。静态分配的<code>IP</code>地址不受租期时长的限制，使用期限为无限长。</p><p><code>DHCP</code>客户端不会等到租期到期后再申请<code>IP</code>地址，这样会导致<code>IP</code>地址被服务器回收，然后分配给其他客户端。为保证能够使用原来的<code>IP</code>地址，客户端会在租期到期前的某个时间点就开始申请延长租期。</p><ul><li>地址池</li></ul><p>指的是<code>DHCP</code>服务器可以为客户端分配的所有<code>IP</code>地址的集合。除<code>IP</code>地址外，地址池内还可以配置租期、子网掩码、默认网关等网络参数。在<code>DHCP</code>服务器为客户端分配<code>IP</code>地址时，这些网络参数也一并分配给客户端。根据创建方式的不同，地址池可以分为基于接口方式的地址池和基于全局方式的地址池。</p><p>基于接口方式的地址池：在<code>DHCP</code>服务器与客户端相连的接口上配置<code>IP</code>地址，地址池是跟此接口地址所属同一网段的<code>IP</code>地址，且地址池中地址只能分配给此接口下的客户端。这种配置方式简单，仅适用于<code>DHCP</code>服务器与客户端在同一个网段的场景。</p><p>基于全局方式的地址池：在系统视图下创建指定网段的地址池，且地址池中地址可以分配给设备所有接口下的客户端。当<code>DHCP</code>务器与客户端不在同一个网段时，需要部署<code>DHCP</code>中继。</p></blockquote><p>（3）选择阶段</p><p>如果有多个<code>DHCP</code>服务器向<code>DHCP</code>客户端回应<code>DHCP OFFER</code>报文，则<code>DHCP</code>客户端一般只接收第一个收到的<code>DHCP OFFER</code>报文，然后以广播方式发送<code>DHCP REQUEST</code>报文，该报文中包含客户端想选择的<code>DHCP</code>服务器标识符（即<code>Option54</code>）和客户端<code>IP</code>地址（即<code>Option50</code>，填充了接收的<code>DHCP OFFER</code>报文中<code>yiaddr</code>字段的<code>IP</code>地址）。</p><p><code>DHCP</code>客户端广播发送<code>DHCP REQUEST</code>报文通知所有的<code>DHCP</code>服务器，它将选择某个<code>DHCP</code>服务器提供的<code>IP</code>地址，其他<code>DHCP</code>服务器可以重新将曾经分配给客户端的<code>IP</code>地址分配给其他客户端。</p><p>（4）确认阶段</p><p>当<code>DHCP</code>服务器收到<code>DHCP</code>客户端发送的<code>DHCP REQUEST</code>报文后，<code>DHCP</code>服务器回应<code>DHCP ACK</code>报文，表示<code>DHCP REQUEST</code>报文中请求的<code>IP</code>地址分配给客户端使用。</p><p>一旦客户端收到 <code>DHCP ACK</code> 后，交互便完成了，并且客户端能够在租用期内使用 <code>DHCP</code> 服务器分配的 <code>IP</code> 地址。</p><h5 id="_2-4-2-有中继场景时dhcp客户端首次接入网络" tabindex="-1">2.4.2 有中继场景时DHCP客户端首次接入网络 <a class="header-anchor" href="#_2-4-2-有中继场景时dhcp客户端首次接入网络" aria-label="Permalink to &quot;2.4.2 有中继场景时DHCP客户端首次接入网络&quot;">​</a></h5><p>从上边了解到<code>DHCP</code>用的是广播，那如果 <code>DHCP</code> 服务器和客户端不是在同一个局域网内，路由器又不会转发广播包，那不是每个网络都要配一个 <code>DHCP</code> 服务器？为了解决这一问题，就出现了 <code>DHCP</code> 中继代理。有了 <code>DHCP</code> 中继代理以后，对不同网段的 <code>IP</code> 地址分配也可以由一个 <code>DHCP</code> 服务器统一进行管理。</p><img src="'+D+'" alt="image-20220618093006767" style="zoom:50%;">',75)])])}const w=d(p,[["render",C]]);export{u as __pageData,w as default};
